-- FinTCC: esquema PostgreSQL. Toda informação pessoal tem dono explícito.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE perfil_acesso AS ENUM ('usuario','administrador'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE tipo_movimento AS ENUM ('receita','despesa'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE recorrencia AS ENUM ('unica','mensal'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE status_importacao AS ENUM ('enviada','revisada','importada','cancelada'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS usuarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, senha_hash text NOT NULL, nome text NOT NULL, foto_url text, renda_mensal numeric(12,2), pessoas_familia smallint NOT NULL DEFAULT 1 CHECK(pessoas_familia>0), perfil perfil_acesso NOT NULL DEFAULT 'usuario', consentimento_dados_em timestamptz NOT NULL DEFAULT now(), consentimento_renda_em timestamptz, consentimento_ia_em timestamptz, criado_em timestamptz NOT NULL DEFAULT now(), atualizado_em timestamptz NOT NULL DEFAULT now());
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS consentimento_dados_em timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS categorias (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid REFERENCES usuarios(id) ON DELETE CASCADE, nome text NOT NULL, tipo tipo_movimento NOT NULL, icone text, cor text, UNIQUE(usuario_id,nome,tipo));
CREATE TABLE IF NOT EXISTS receitas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, categoria_id uuid REFERENCES categorias(id) ON DELETE SET NULL, descricao text NOT NULL, valor numeric(12,2) NOT NULL CHECK(valor>0), data date NOT NULL, recorrencia recorrencia NOT NULL DEFAULT 'unica', origem text NOT NULL DEFAULT 'manual', criado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cartoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, nome text NOT NULL, bandeira text NOT NULL, limite numeric(12,2) NOT NULL CHECK(limite>=0), dia_fechamento smallint NOT NULL CHECK(dia_fechamento BETWEEN 1 AND 31), dia_vencimento smallint NOT NULL CHECK(dia_vencimento BETWEEN 1 AND 31), criado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS despesas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, categoria_id uuid REFERENCES categorias(id) ON DELETE SET NULL, cartao_id uuid REFERENCES cartoes(id) ON DELETE SET NULL, descricao text NOT NULL, valor numeric(12,2) NOT NULL CHECK(valor>0), data date NOT NULL, forma_pagamento text NOT NULL CHECK(forma_pagamento IN ('dinheiro','debito','credito','pix','transferencia','outro')), parcelas smallint NOT NULL DEFAULT 1 CHECK(parcelas>0), recorrencia recorrencia NOT NULL DEFAULT 'unica', origem text NOT NULL DEFAULT 'manual', criado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS faturas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, cartao_id uuid NOT NULL REFERENCES cartoes(id) ON DELETE CASCADE, mes date NOT NULL, vencimento date NOT NULL, valor numeric(12,2) NOT NULL DEFAULT 0, paga_em date, UNIQUE(cartao_id,mes));
CREATE TABLE IF NOT EXISTS parcelas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, despesa_id uuid NOT NULL REFERENCES despesas(id) ON DELETE CASCADE, numero smallint NOT NULL, total smallint NOT NULL, valor numeric(12,2) NOT NULL CHECK(valor>0), vencimento date NOT NULL, paga_em date, UNIQUE(despesa_id,numero));
CREATE TABLE IF NOT EXISTS metas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, nome text NOT NULL, valor_alvo numeric(12,2) NOT NULL CHECK(valor_alvo>0), valor_guardado numeric(12,2) NOT NULL DEFAULT 0 CHECK(valor_guardado>=0), prazo date, aporte_mensal numeric(12,2) NOT NULL DEFAULT 0, criada_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS importacoes_extrato (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, nome_arquivo text NOT NULL, formato text NOT NULL CHECK(formato IN ('csv','ofx')), status status_importacao NOT NULL DEFAULT 'enviada', registros jsonb NOT NULL DEFAULT '[]', sha256 text, criado_em timestamptz NOT NULL DEFAULT now(), confirmado_em timestamptz);
CREATE TABLE IF NOT EXISTS relatorios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, periodo_inicio date NOT NULL, periodo_fim date NOT NULL, tipo text NOT NULL, arquivo_url text, criado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cursos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, titulo text NOT NULL, descricao text NOT NULL, conteudo jsonb NOT NULL, duracao_minutos smallint NOT NULL DEFAULT 10, publicado boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS progresso_cursos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, curso_id uuid NOT NULL REFERENCES cursos(id) ON DELETE CASCADE, etapa_atual smallint NOT NULL DEFAULT 0, concluido_em timestamptz, atualizado_em timestamptz NOT NULL DEFAULT now(), UNIQUE(usuario_id,curso_id));
CREATE TABLE IF NOT EXISTS conversas_ia (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, papel text NOT NULL CHECK(papel IN ('usuario','assistente')), mensagem text NOT NULL, modelo text, criado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS correcoes_categorizacao (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), usuario_id uuid NOT NULL REFERENCES usuarios(id) ON DELETE CASCADE, descricao_normalizada text NOT NULL, tipo tipo_movimento NOT NULL, categoria_id uuid NOT NULL REFERENCES categorias(id) ON DELETE CASCADE, ocorrencias integer NOT NULL DEFAULT 1, atualizado_em timestamptz NOT NULL DEFAULT now(), UNIQUE(usuario_id,descricao_normalizada,tipo));
CREATE TABLE IF NOT EXISTS preferencias_usuario (usuario_id uuid PRIMARY KEY REFERENCES usuarios(id) ON DELETE CASCADE, tema text NOT NULL DEFAULT 'claro' CHECK(tema IN ('claro','escuro')), consentimento_ia_em timestamptz, consentimento_renda_em timestamptz, consentimento_revogado_em timestamptz, atualizado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessoes_web (sid varchar NOT NULL PRIMARY KEY, sess json NOT NULL, expire timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessoes_web_expire_idx ON sessoes_web(expire);
CREATE INDEX IF NOT EXISTS receitas_usuario_data_idx ON receitas(usuario_id,data DESC);
CREATE INDEX IF NOT EXISTS despesas_usuario_data_idx ON despesas(usuario_id,data DESC);
CREATE INDEX IF NOT EXISTS despesas_usuario_categoria_idx ON despesas(usuario_id,categoria_id,data DESC);
CREATE INDEX IF NOT EXISTS conversas_usuario_data_idx ON conversas_ia(usuario_id,criado_em DESC);
-- Habilite políticas RLS por tabela depois de definir como a API valida a sessão.
ALTER TABLE receitas ENABLE ROW LEVEL SECURITY;
ALTER TABLE despesas ENABLE ROW LEVEL SECURITY;
ALTER TABLE metas ENABLE ROW LEVEL SECURITY;
ALTER TABLE cartoes ENABLE ROW LEVEL SECURITY;
ALTER TABLE faturas ENABLE ROW LEVEL SECURITY;
ALTER TABLE parcelas ENABLE ROW LEVEL SECURITY;
ALTER TABLE importacoes_extrato ENABLE ROW LEVEL SECURITY;
ALTER TABLE relatorios ENABLE ROW LEVEL SECURITY;
ALTER TABLE progresso_cursos ENABLE ROW LEVEL SECURITY;
ALTER TABLE conversas_ia ENABLE ROW LEVEL SECURITY;
ALTER TABLE correcoes_categorizacao ENABLE ROW LEVEL SECURITY;
ALTER TABLE categorias ENABLE ROW LEVEL SECURITY;
ALTER TABLE preferencias_usuario ENABLE ROW LEVEL SECURITY;

-- As transações da API definem app.user_id a partir da sessão autenticada.
DROP POLICY IF EXISTS categorias_proprias ON categorias;
CREATE POLICY categorias_proprias ON categorias USING (usuario_id IS NULL OR usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS preferencias_proprias ON preferencias_usuario;
CREATE POLICY preferencias_proprias ON preferencias_usuario USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS receitas_proprias ON receitas;
CREATE POLICY receitas_proprias ON receitas USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS despesas_proprias ON despesas;
CREATE POLICY despesas_proprias ON despesas USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS metas_proprias ON metas;
CREATE POLICY metas_proprias ON metas USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS cartoes_proprios ON cartoes;
CREATE POLICY cartoes_proprios ON cartoes USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS faturas_proprias ON faturas;
CREATE POLICY faturas_proprias ON faturas USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS parcelas_proprias ON parcelas;
CREATE POLICY parcelas_proprias ON parcelas USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS importacoes_proprias ON importacoes_extrato;
CREATE POLICY importacoes_proprias ON importacoes_extrato USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS relatorios_proprios ON relatorios;
CREATE POLICY relatorios_proprios ON relatorios USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS progresso_proprio ON progresso_cursos;
CREATE POLICY progresso_proprio ON progresso_cursos USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS conversas_proprias ON conversas_ia;
CREATE POLICY conversas_proprias ON conversas_ia USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
DROP POLICY IF EXISTS correcoes_proprias ON correcoes_categorizacao;
CREATE POLICY correcoes_proprias ON correcoes_categorizacao USING (usuario_id::text = current_setting('app.user_id',true)) WITH CHECK (usuario_id::text = current_setting('app.user_id',true));
ALTER TABLE categorias FORCE ROW LEVEL SECURITY;
ALTER TABLE preferencias_usuario FORCE ROW LEVEL SECURITY;
ALTER TABLE receitas FORCE ROW LEVEL SECURITY;
